.bio-card {
  scroll-snap-align: center;
  scroll-margin: 0;
}


.bio-card-preview {
  width: 100%;
}

.bio-wrapper {
  top: 0;
  bottom: 0;
  min-height: auto;
  height: auto;
  scroll-snap-type: x mandatory;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.bio-wrapper::-webkit-scrollbar {
  display: none;
}

.bio-card:nth-child(even) {
    margin-top: 60px;
  }

  .bio-card:nth-child(odd) {
    margin-top: 0;
  }
@media (min-width: 768px) {






  .bio-wrapper {
    min-height: 100vh;
  }
}

.extended-wrapper {
  overflow: scroll;
}
